1	#Requires -Version 7.0
2	<#
3	.SYNOPSIS
4	    Replaces or adds exactly one acceptance criterion on a TR or TEST record through the plugin
5	    (getTr/getTest, then updateTr/updateTest with the full list), then reads the record back and
6	    proves that only the named criterion changed. Supports -WhatIf.
7	.PARAMETER DataFile
8	    PowerShell data file with keys Kind (tr or test), Id, Mode (Replace or Add), and Criterion
9	    (id, text, isSatisfied, optional evidence).
10	#>
11	[CmdletBinding(SupportsShouldProcess)]
12	param(
13	    [Parameter(Mandatory)] [string] $DataFile
14	)
15	
16	Set-StrictMode -Version Latest
17	$ErrorActionPreference = 'Stop'
18	. (Join-Path $PSScriptRoot 'CcPlugin.ps1')
19	
20	function Test-Ok {
21	    param([Parameter(Mandatory)] $Result)
22	    return ($Result.ExitCode -eq 0 -and $Result.Raw -notmatch '(?im)^\s*type:\s*error')
23	}
24	
25	function Get-Signature {
26	    param($Criterion)
27	    return ('{0}|{1}|{2}|{3}' -f (Get-CcValue $Criterion 'id'), (Get-CcValue $Criterion 'text'), [bool](Get-CcValue $Criterion 'isSatisfied'), (Get-CcValue $Criterion 'evidence'))
28	}
29	
30	function Read-CriterionList {
31	    param([string]$GetMethod, [string]$Id)
32	    $g = Invoke-CcPlugin -Method $GetMethod -Params ([ordered]@{ id = $Id })
33	    if (-not (Test-Ok $g)) { Write-Output $g.Raw; throw "Read of $Id failed" }
34	    $result = Get-CcValue (Get-CcValue $g.Parsed 'payload') 'result'
35	    return @(Get-CcValue $result 'acceptanceCriteria' | Where-Object { $null -ne $_ })
36	}
37	
38	$data = Import-PowerShellDataFile -LiteralPath $DataFile
39	$kind = [string]$data.Kind
40	$id = [string]$data.Id
41	$mode = [string]$data.Mode
42	$new = $data.Criterion
43	if ($kind -notin 'tr', 'test') { throw "Kind must be tr or test, got '$kind'" }
44	if ($mode -notin 'Replace', 'Add') { throw "Mode must be Replace or Add, got '$mode'" }
45	$getMethod = if ($kind -eq 'tr') { 'workflow.requirements.getTr' } else { 'workflow.requirements.getTest' }
46	$updateMethod = if ($kind -eq 'tr') { 'workflow.requirements.updateTr' } else { 'workflow.requirements.updateTest' }
47	
48	Write-Output "Now: $((Get-Date).ToString('s')) $id $mode criterion $($new.id)"
49	$before = @(Read-CriterionList -GetMethod $getMethod -Id $id)
50	$ids = @($before | ForEach-Object { [string](Get-CcValue $_ 'id') })
51	if ($mode -eq 'Replace' -and $ids -notcontains $new.id) { throw "Criterion $($new.id) not found on $id" }
52	if ($mode -eq 'Add' -and $ids -contains $new.id) { throw "Criterion $($new.id) already exists on $id" }
53	
54	$newItem = [ordered]@{ id = [string]$new.id; text = [string]$new.text; isSatisfied = [bool]$new.isSatisfied }
55	if ($new.ContainsKey('evidence') -and $new.evidence) { $newItem.evidence = [string]$new.evidence }
56	$list = @(foreach ($c in $before) {
57	    if ($mode -eq 'Replace' -and [string](Get-CcValue $c 'id') -eq $new.id) { $newItem; continue }
58	    $item = [ordered]@{ id = [string](Get-CcValue $c 'id'); text = [string](Get-CcValue $c 'text'); isSatisfied = [bool](Get-CcValue $c 'isSatisfied') }
59	    $evidence = Get-CcValue $c 'evidence'
60	    if ($evidence) { $item.evidence = [string]$evidence }
61	    $item
62	})
63	if ($mode -eq 'Add') { $list += $newItem }
64	Write-Output ('Criteria before={0} after={1}' -f $before.Count, $list.Count)
65	
66	if (-not $PSCmdlet.ShouldProcess("$id criterion $($new.id)", "$updateMethod ($mode)")) { return }
67	$u = Invoke-CcPlugin -Method $updateMethod -Params ([ordered]@{ id = $id; acceptanceCriteria = $list })
68	Write-Output "$updateMethod exit=$($u.ExitCode) ok=$(Test-Ok $u)"
69	if (-not (Test-Ok $u)) { Write-Output $u.Raw; exit 1 }
70	
71	$after = @(Read-CriterionList -GetMethod $getMethod -Id $id)
72	$beforeById = @{}
73	foreach ($c in $before) { $beforeById[[string](Get-CcValue $c 'id')] = Get-Signature $c }
74	$changed = @()
75	foreach ($c in $after) {
76	    $cid = [string](Get-CcValue $c 'id')
77	    if (-not $beforeById.ContainsKey($cid) -or $beforeById[$cid] -ne (Get-Signature $c)) { $changed += $cid }
78	}
79	$expectedNew = Get-Signature $newItem
80	$target = @($after | Where-Object { [string](Get-CcValue $_ 'id') -eq $new.id })
81	$ok = ($changed.Count -eq 1 -and $changed[0] -eq $new.id -and $target.Count -eq 1 -and (Get-Signature $target[0]) -eq $expectedNew -and $after.Count -eq $list.Count)
82	Write-Output ('READBACK {0}: criteria={1} changed=[{2}] targetMatches={3} ok={4}' -f $id, $after.Count, ($changed -join ','), ($target.Count -eq 1 -and (Get-Signature $target[0]) -eq $expectedNew), $ok)
83	if (-not $ok) { exit 1 }
84

